		DefenceCounterclaimText:
			"The Defendant, in its counter-affidavit, contends that the Plaintiff lacks authority to impose duties on instruments between individuals or companies, as stamp duties fall under the Exclusive Legislative List of the National Assembly. It asserts that stamp duty applies to bank receipts, not private transactions, and argues that no cause of action exists against the 6th Defendant, urging the court to dismiss the suit or strike out its name.",
