		BackgroundFacts:
			"The Claimant, a debtor customer of the Bank, challenges the Bank’s right to sell a secured property. It also raises claims against Grimaldi Agency Nig. Ltd. relating to the non-delivery of equipment purchased with a loan facility. Specifically, the Claimant alleges that the Bank denied financing the equipment transaction when invited by the EFCC, causing the EFCC to discontinue investigations. The Bank disputes these allegations and contends that the suit is merely a ploy by the Claimant to frustrate recovery of its indebtedness. The matter was initially instituted at the Federal High Court (Suit No. FHC/L/CS/1785/13) but was transferred to the Lagos State High Court on grounds of jurisdiction.",
		ReliefsSought:
			"The Claimant seeks declarations confirming its entitlement to delivery of a Caterpillar Wheel Loader (Chassis No. 950197581J8208) and recovery of its full purchase value of USD 105,000 as at March 2009. It also claims: USD 105,000 being the value of the equipment, ₦75,000,000 as damages for negligent misstatement and denial of financing before the EFCC, and ₦10,000,000 as costs of action.",
		DefenceCounterclaimText:
			"The Bank maintains that it had no contractual relationship with the Claimant in respect of the Caterpillar transaction. It clarifies that the only subsisting transaction with the Claimant was an Import Finance Facility (IFF) of ₦28,000,000 granted in February 2008 for the purchase of 120 used heavy-duty trucks from Hamburg, Germany. The Claimant defaulted, and its indebtedness rose to ₦69,356,043.03. The Bank asserts that its demand letters related solely to the IFF and not to the Caterpillar transaction, which was outside its knowledge or involvement.",
		StatusDetails:
			"The matter came up sometime in November 2024 for trial. However, Counsel informed the Court of the need for joinder of AMCON and NPA, and an application to that effect was filed and was ripe for hearing. The said application was taken and accordingly granted. The Court thereafter directed the parties to explore settlement through mediation at the LMDC. On 18th August 2025, counsel on record attended a mediation session before the Lagos State High Court. The Claimants, however, failed to attend the session. When the case recently came up for further mention on 6th October 2025, the parties reported that no significant progress had been made towards settlement. The matter was consequently adjourned to 8th December 2025 for report of settlement.",
		RemarksRecommendation:
			"The Claimant’s case appears to be an attempt to frustrate debt recovery by linking the Bank to a Caterpillar transaction in which it had no involvement. The Bank’s position seems well supported by the Import Finance Facility (IFF) documentation, which establishes that the only valid relationship was for the purchase of 120 used trucks, under which the Claimant remains indebted in excess of ₦69 million. If there is no independent action already pending to recover this indebtedness, it may be prudent for counsel to consider entering a counterclaim in this suit to ensure the Bank’s recovery position is not sidelined. During mediation or settlement discussions, emphasis should be placed on repayment of the outstanding facility, while maintaining that the Caterpillar transaction was unknown to the Bank. If the trial court makes adverse findings on the Caterpillar issue, an Appeal should be considered, but a counterclaim would ensure the Bank’s debt claim remains live before the court.",
