			"The Applicant, Japaul Energy Limited, sought interlocutory and Mareva injunctions against Ecobank Nigeria in respect of two promissory notes (Nos. FGN/PN.OMC/S3/2020/17A and 17B), allegedly diverted from Sterling Bank and said to be domiciled with Ecobank. The value of the notes was put at ₦517,019,812. The reliefs sought included directing Ecobank to pay the value of the notes into the court’s registry, restraining it from permitting access to the notes’ proceeds, and mandating sequestration of related receivables, subsidy payments, and foreign exchange allocations.",
