			"The Claimant seeks declarations that the suspension of his account and BVN are unlawful, null and void under the BOFIA and CBN Acts, and that such actions amount to breaches of his contractual and constitutional rights. He also seeks an order lifting the restrictions on his account and BVN, special damages of ₦20,000,000, general damages of ₦100,000,000, a refund of ₦3,000,000 legal fees, and costs of the action.",
		DefenceCounterclaimText:
			"No substantive defence has been recorded in the case file at this stage. However, it is anticipated that the Bank’s defence will rely on the regulatory framework of the CBN, including its powers to mandate BVN watch-listing and account restrictions where there is suspicion of fraudulent transactions, to demonstrate that the restriction was lawfully applied in compliance with its obligations.",
		StatusDetails: "The case is slated to commence trial on 12 November 2025.",
		RemarksRecommendation:
			"The Bank’s counsel should ensure that the defence clearly establishes that the account restriction and BVN blacklisting were carried out in compliance with CBN directives and pursuant to regulatory obligations, rather than any unilateral action by the Bank. Emphasis should be placed on distinguishing between regulatory enforcement measures and breaches of fundamental rights, in order to demonstrate that the Claimant’s suit is misconceived. It is recommended that counsel prepare to rely on precedent where the courts have upheld the regulatory powers of the CBN and the corresponding obligations of commercial banks to comply.",
